#!/bin/bash
set -eo pipefail
task_root=/data1/home/sunyiq/china_radiation_16_hpc_20261012_001/execution_v1
test ! -e "$task_root"
mkdir "$task_root"
mkdir "$task_root/logs"
umask 077
cd "$task_root"
/data1/home/sunyiq/miniconda3/envs/nh_final/bin/python -B - <<'OWN_DEPLOY_PY'
import base64,gzip,hashlib,io,json,tarfile
from pathlib import Path
packet=base64.b64decode('',validate=True)
assert hashlib.sha256(packet).hexdigest()=='1acf824677892686965bf689484aea51b9ea6ef402ff9b87c2b23117a2afb106'
with Path('INITIAL_PACKET.tar.gz').open('xb') as f:f.write(packet)
with tarfile.open(fileobj=io.BytesIO(gzip.decompress(packet)),mode='r:') as t:
 items=t.getmembers();assert len(items)==6 and len({x.name for x in items})==6
 assert all(x.isfile() and x.name==Path(x.name).name and x.size<=1048576 for x in items)
 for x in items:
  raw=t.extractfile(x).read();assert len(raw)==x.size
  with Path(x.name).open('xb') as f:f.write(raw)
for row in json.loads(Path('DEPLOYMENT_MANIFEST.json').read_bytes())['files']:
 raw=Path(row['file']).read_bytes()
 assert len(raw)==row['bytes'] and hashlib.sha256(raw).hexdigest()==row['sha256']
 print('OWN_REQUEST_DEPLOY_SHA256='+row['sha256']+' '+row['file'])
OWN_DEPLOY_PY
set +e
task_submission=$(timeout 20s sbatch build_raw_requests.sbatch 2>&1)
task_exit=$?
set -e
printf '%s\n' "$task_submission" > SUBMISSION_OUTPUT.txt
printf '%s\nOWN_REQUEST_BUILD_SUBMIT_EXIT=%s\n' "$task_submission" "$task_exit"
test "$task_exit" -eq 0
if [[ "$task_submission" =~ ^Submitted\ batch\ job\ ([0-9]+)$ ]]; then
 task_job="${BASH_REMATCH[1]}"
else printf 'OWN_REQUEST_BUILD_SUBMISSION_UNCERTAIN_NO_RETRY\n';exit 1;fi
printf '%s\n' "$task_job" > OWN_REQUEST_BUILD_JOB_ID.txt
printf 'OWN_REQUEST_BUILD_JOB_ID=%s\nOWN_REQUEST_BUILD_DEPLOY_DONE\n' "$task_job"
